const statusEvidence=[...routes,source('pkg/registry/apps/deployment/strategy.go','169-195','Status updates preserve spec/labels and drop disabled terminating counts only if not previously in use.'),apps('678-706','Status validation checks nonnegative values and observed-count relationships.'),source('pkg/controller/deployment/sync.go','480-537','The controller calculates replica observations from ReplicaSets and publishes status.')];
const statusScope='Kubernetes v1.35.0 Deployment normal create/update and the separate /status update endpoint after fresh JSON decoding; controller status publication where stated.';
const statusChange='Normal create clears submitted status and normal update preserves stored status. A valid /status update changes observed status, preserving spec and labels. The Deployment controller can publish later observations.';
function statusRecord(path,purpose,omitted,empty,invalid,options={}){add(path,purpose,omitted,empty,invalid,statusEvidence,{...options,changeImpact:statusChange,receiver:'Deployment API normal/status strategy and Deployment controller status publisher'});records.get(path).operationScope=statusScope;}
statusRecord('$.status','Report the controller observed Deployment state.','The fresh status is zero; normal create clears it and a normal update preserves the stored status.','{} has zero counts and no conditions and passes numeric status validation on /status.','On /status, negative counts, updated/ready/available above replicas or available above ready reject validation. Submitted conditions are not independently enumerated by this numeric validator.');
